/* Embedded resources for the standalone tcc.exe (win32/build-standalone.sh).
 *
 * The standalone tcc.exe carries its headers and runtime files (libtcc1.a, *.def) inside the executable and
 * serves them from memory: libtcc.c, built with -DEMBEDDED_RESOURCES, asks tcc_get_embedded_header() before it
 * opens a header, falls back to tcc_open_embedded_runtime() when a runtime file is not on disk, and routes
 * read/lseek/close through the tcc_vfd_* wrappers below. No temp files, no disk I/O for embedded files.
 *
 * The data itself is generated by build-standalone.sh: embedded_headers.h and embedded_runtime_files.c.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <windows.h>
#include <io.h>  /* _read, _lseek, _close */
#include <fcntl.h>  /* SEEK_* constants */

/* Runtime file structure */
typedef struct {
    const char *filename;
    const unsigned char *data;
    size_t size;
} EmbeddedFile;

/* Virtual file descriptor state */
typedef struct {
    const unsigned char *data;
    size_t size;
    size_t position;
    int in_use;
} VirtualFD;

#define MAX_VIRTUAL_FDS 32
#define VIRTUAL_FD_BASE 10000  /* Virtual FDs start at 10000 (high positive numbers) */

/* Forward declarations */
extern const int embedded_runtime_count;
const EmbeddedFile* get_embedded_runtime_files(void);

/* Virtual FD table */
static VirtualFD virtual_fds[MAX_VIRTUAL_FDS] = {0};

/* Find embedded file by name or path */
static const EmbeddedFile* find_embedded_file(const char *path) {
    const EmbeddedFile *runtime_files;
    const char *basename;
    const char *path_basename;
    int i;

    if (!path)
        return NULL;

    runtime_files = get_embedded_runtime_files();

    /* Extract basename from path - handle both / and \ */
    basename = strrchr(path, '\\');
    path_basename = strrchr(path, '/');

    /* Use whichever separator appears last */
    if (basename && path_basename) {
        basename = (basename > path_basename) ? basename + 1 : path_basename + 1;
    } else if (path_basename) {
        basename = path_basename + 1;
    } else if (basename) {
        basename = basename + 1;
    } else {
        basename = path;
    }

    /* Search for matching file by basename */
    for (i = 0; i < embedded_runtime_count; i++) {
        if (strcmp(runtime_files[i].filename, basename) == 0) {
            return &runtime_files[i];
        }
    }

    /* Also try case-insensitive match on Windows */
    for (i = 0; i < embedded_runtime_count; i++) {
        if (_stricmp(runtime_files[i].filename, basename) == 0) {
            return &runtime_files[i];
        }
    }

    return NULL;
}

/* Allocate a virtual FD */
static int alloc_virtual_fd(const unsigned char *data, size_t size) {
    int i;

    for (i = 0; i < MAX_VIRTUAL_FDS; i++) {
        if (!virtual_fds[i].in_use) {
            virtual_fds[i].data = data;
            virtual_fds[i].size = size;
            virtual_fds[i].position = 0;
            virtual_fds[i].in_use = 1;
            return VIRTUAL_FD_BASE + i;  /* Return positive FD (10000+) */
        }
    }

    return -1;  /* No free slots */
}

/* Get virtual FD state */
static VirtualFD* get_virtual_fd(int fd) {
    int index;

    if (fd < VIRTUAL_FD_BASE) {
        return NULL;  /* Not a virtual FD */
    }

    index = fd - VIRTUAL_FD_BASE;
    if (index < 0 || index >= MAX_VIRTUAL_FDS) {
        return NULL;
    }

    if (!virtual_fds[index].in_use) {
        return NULL;
    }

    return &virtual_fds[index];
}

/* Free a virtual FD */
static void free_virtual_fd(int fd) {
    VirtualFD *vfd = get_virtual_fd(fd);
    if (vfd) {
        vfd->in_use = 0;
    }
}

/* Hook for _tcc_open to serve embedded runtime files from memory */
int tcc_open_embedded_runtime(const char *filename) {
    const EmbeddedFile *embedded;
    int vfd;

    /* Check if this is an embedded runtime file */
    embedded = find_embedded_file(filename);
    if (!embedded) {
        return -1;  /* Not an embedded file */
    }

    /* Allocate virtual FD */
    vfd = alloc_virtual_fd(embedded->data, embedded->size);

    return vfd;
}

/* Virtual read operation */
int tcc_vfd_read(int fd, void *buf, unsigned int count) {
    VirtualFD *vfd = get_virtual_fd(fd);
    size_t bytes_to_read;
    size_t bytes_available;

    if (!vfd) {
        /* Not a virtual FD, use real read */
        return _read(fd, buf, count);
    }

    /* Virtual FD - read from memory */
    bytes_available = vfd->size - vfd->position;
    bytes_to_read = (count < bytes_available) ? count : bytes_available;

    if (bytes_to_read > 0) {
        memcpy(buf, vfd->data + vfd->position, bytes_to_read);
        vfd->position += bytes_to_read;
    }

    return (int)bytes_to_read;
}

/* Virtual lseek operation */
long tcc_vfd_lseek(int fd, long offset, int whence) {
    VirtualFD *vfd = get_virtual_fd(fd);
    long new_pos;

    if (!vfd) {
        /* Not a virtual FD, use real lseek */
        return _lseek(fd, offset, whence);
    }

    /* Virtual FD - seek in memory */
    switch (whence) {
        case SEEK_SET:
            new_pos = offset;
            break;
        case SEEK_CUR:
            new_pos = vfd->position + offset;
            break;
        case SEEK_END:
            new_pos = vfd->size + offset;
            break;
        default:
            errno = EINVAL;
            return -1;
    }

    if (new_pos < 0 || (size_t)new_pos > vfd->size) {
        errno = EINVAL;
        return -1;
    }

    vfd->position = new_pos;
    return new_pos;
}

/* Virtual close operation */
int tcc_vfd_close(int fd) {
    VirtualFD *vfd = get_virtual_fd(fd);

    if (!vfd) {
        /* Not a virtual FD, use real close */
        return _close(fd);
    }

    /* Virtual FD - just free it */
    free_virtual_fd(fd);
    return 0;
}

/* No runtime extraction needed */
const char* tcc_extract_runtime(void) {
    return ".";
}

/* No cleanup needed */
void tcc_cleanup_runtime(void) {
    memset(virtual_fds, 0, sizeof(virtual_fds));
}

/* ---- headers ------------------------------------------------------------------------------------------------
 * Keys are the install layout of a Windows tcc ("include/<rel>", win32/include overriding include/, as
 * `make install` lays it out). tcc asks for "<tccdir>/include/<rel>", so a header matches when the requested
 * path ends with "/<key>" (or is the key). Case-insensitive, either slash. No basename fallback: the layout has
 * the same basename in several places (time.h and sys/time.h, fcntl.h and sys/fcntl.h, ...).
 */
#include "embedded_headers.h"

const char* tcc_get_embedded_header(const char *path) {
    char normalized[1024];
    size_t len, klen;
    int i;

    /* copy with '/' separators, resolving "." and ".." segments ("include/tcc/../math.h" -> "include/math.h") */
    {
        const char *p = path;
        len = 0;
        while (*p) {
            const char *seg = p;
            size_t slen;
            while (*p && *p != '/' && *p != '\\')
                p++;
            slen = (size_t)(p - seg);
            if (*p)
                p++;
            if (slen == 0 && seg != path)
                continue;                                       /* "//" */
            if (slen == 1 && seg[0] == '.')
                continue;
            if (slen == 2 && seg[0] == '.' && seg[1] == '.' && len > 0) {
                while (len > 0 && normalized[len - 1] != '/')   /* drop the last segment */
                    len--;
                if (len > 0)
                    len--;                                      /* and its separator */
                continue;
            }
            if (len + slen + 2 >= sizeof(normalized))
                return NULL;
            if (seg != path)
                normalized[len++] = '/';
            memcpy(normalized + len, seg, slen);
            len += slen;
        }
        normalized[len] = '\0';
    }

    for (i = 0; embedded_headers[i].path != NULL; i++) {
        klen = strlen(embedded_headers[i].path);
        if (klen > len)
            continue;
        if (_stricmp(normalized + len - klen, embedded_headers[i].path) != 0)
            continue;
        if (klen == len || normalized[len - klen - 1] == '/')
            return embedded_headers[i].content;
    }
    return NULL;
}
